// TriggerIrrigation handles irrigation trigger requests.
func (h *IrrigationHandler) TriggerIrrigation(ctx context.Context, req *connect.Request[pb.TriggerIrrigationRequest]) (*connect.Response[pb.TriggerIrrigationResponse], error) {
	h.log.Infow("msg", "TriggerIrrigation request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetScheduleId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "schedule_id is required")
	}
	evt, err := h.svc.TriggerIrrigation(ctx, req.Msg.GetScheduleId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.TriggerIrrigationResponse{Event: mappers.EventToProto(evt)}), nil
}

// StopIrrigation handles irrigation stop requests.
func (h *IrrigationHandler) StopIrrigation(ctx context.Context, req *connect.Request[pb.StopIrrigationRequest]) (*connect.Response[pb.StopIrrigationResponse], error) {
	h.log.Infow("msg", "StopIrrigation request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetEventId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "event_id is required")
	}
	// Get the event, then cancel the associated schedule to stop irrigation
	evt, err := h.svc.GetEvent(ctx, req.Msg.GetEventId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	if err := h.svc.CancelSchedule(ctx, evt.ScheduleID); err != nil {
		return nil, errors.ToConnectError(err)
	}
	// Re-fetch the event to get updated state
	evt, err = h.svc.GetEvent(ctx, req.Msg.GetEventId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.StopIrrigationResponse{Event: mappers.EventToProto(evt)}), nil
}

