// GetWaterUsage handles water usage reporting requests.
func (h *IrrigationHandler) GetWaterUsage(ctx context.Context, req *connect.Request[pb.GetWaterUsageRequest]) (*connect.Response[pb.GetWaterUsageResponse], error) {
	if req.Msg.GetZoneId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "zone_id is required")
	}
	from := time.Time{}
	to := time.Now()
	if req.Msg.GetFrom() != nil {
		from = req.Msg.GetFrom().AsTime()
	}
	if req.Msg.GetTo() != nil {
		to = req.Msg.GetTo().AsTime()
	}
	logs, err := h.svc.GetWaterUsage(ctx, req.Msg.GetZoneId(), from, to)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	var totalLiters float64
	for i := range logs {
		totalLiters += logs[i].WaterLiters
	}
	return connect.NewResponse(&pb.GetWaterUsageResponse{
		Logs:        mappers.WaterUsageLogsToProto(logs),
		TotalLiters: totalLiters,
	}), nil
}

// GetIrrigationHistory handles irrigation history requests.
func (h *IrrigationHandler) GetIrrigationHistory(ctx context.Context, req *connect.Request[pb.GetIrrigationHistoryRequest]) (*connect.Response[pb.GetIrrigationHistoryResponse], error) {
	if req.Msg.GetScheduleId() == "" && req.Msg.GetZoneId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "schedule_id or zone_id is required")
	}
	pageSize := req.Msg.GetPageSize()
	offset := req.Msg.GetPageOffset()

	if req.Msg.GetScheduleId() != "" {
		events, total, err := h.svc.ListEventsBySchedule(ctx, req.Msg.GetScheduleId(), pageSize, offset)
		if err != nil {
			return nil, errors.ToConnectError(err)
		}
		return connect.NewResponse(&pb.GetIrrigationHistoryResponse{
			Events:     mappers.EventsToProto(events),
			TotalCount: total,
		}), nil
	}

	// Fall back to listing by schedule for the zone (use zone_id as schedule filter)
	events, total, err := h.svc.ListEventsBySchedule(ctx, req.Msg.GetZoneId(), pageSize, offset)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.GetIrrigationHistoryResponse{
		Events:     mappers.EventsToProto(events),
		TotalCount: total,
	}), nil
}
